        return np.clip(x, lb, ub)

    x = rng.uniform(lb, ub, size=dim)
    T = 1.0
    cooling_rate = 0.99 / (budget ** 0.6)

    for _ in range(budget):
        y = clip(x + rng.normal(size=dim))
        delta = func(y) - func(x)
        if delta < 0 or rng.random() < np.exp(-delta / T):
            x = y
        T *= cooling_rate

    return x
